#include <bits/stdc++.h>
using namespace std;
int cwDist(int p,int q){ return ((p-q)%40+40)%40*9; }
int ccwDist(int p,int q){ return ((q-p)%40+40)%40*9; }
int main(){
    int pos,a,b,c;
    while(cin>>pos>>a>>b>>c && !(pos==0&&a==0&&b==0&&c==0)){
        long long total=0;
        total += 720 + cwDist(pos,a);
        total += 360 + ccwDist(a,b);
        total += cwDist(b,c);
        cout << total << "\n";
    }
}

